Lemma open_walkB_err : forall (sp path e : Z) (ra gp tp t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    F fc (m : word -> option byte) (lo : Z) (g errv : word) junk,
  stk asegs m lo (sp + -96) -> SEGTOP_A <= lo -> lo + 128 <= sp -> sp < 2^64 -> 1 <= e <= 4095 ->
  rw_cells asegs m (sp + -96) [CB 16 junk; C8 g; C8 s1; C8 s0; C8 ra; C8 a2; C8 a3; C8 a4; C8 a5; C8 a6; C8 a7] ->
  ro_cells asegs m SSP_GUARD [C8 g] -> rw_cells asegs m (bv_unsigned tp + -164) [C4 errv] ->
  164 <= bv_unsigned tp -> bv_unsigned tp + -164 + 4 <= 0x783758 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (m' : word -> option byte),
                 (exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) F' fc',
                 ms' = MS (mkR ra (Z_to_bv 64 sp) gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (-1)) a1' a2' a3' a4' a5' a6' a7'
                              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F' (ret_pc ra) fc' None m' (seg_rom asegs))
                 /\ munch [(sp + -112, sp + -96); (bv_unsigned tp + -164, bv_unsigned tp + -164 + 4)] m m'
                 /\ wmono asegs m m' /\ mem_inv asegs m'
                 /\ rw_cells asegs m' (bv_unsigned tp + -164) [C4 (Z_to_bv 64 e)]
                 /\ stk asegs m' lo sp)
    (MS (mkR (Z_to_bv 64 0x1f3234) (Z_to_bv 64 (sp + -96)) gp tp (Z_to_bv 64 path) t1 t2 (Z_to_bv 64 0) (Z_to_bv 64 SSP_GUARD)
             (Z_to_bv 64 (- e)) (Z_to_bv 64 path) (Z_to_bv 64 0x8000) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0)
             (Z_to_bv 64 0) (Z_to_bv 64 56) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x204710) fc None m (seg_rom asegs)).
